/** One of Holi's marks: its paths in their own box, and how they fill. */
export interface BrandMarkShape {
  width: number
  height: number
  paths: readonly string[]
  /** The wordmark's counters (the holes in o and h) are cut by even-odd. */
  fillRule: 'nonzero' | 'evenodd'
}

